import java.awt.FontMetrics;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.image.BufferedImage;

public class TestClass {
    private int getSquareSize(FontMetrics fm) { return 10; } // Placeholder

    public int calculateWidth(FontMetrics fontMetrics) {
        int width = 2 * fontMetrics.getAverageCharWidth() + getSquareSize(fontMetrics);
        return width;
    }

    public static void main(String[] args) {
        BufferedImage img = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics g = img.getGraphics();
        FontMetrics fm = g.getFontMetrics(new Font("Arial", Font.PLAIN, 12));
        TestClass tc = new TestClass();
        System.out.println(tc.calculateWidth(fm));
        g.dispose(); // Clean up graphics context
    }
}

